pub static BISHOP_MASKS: [u64; 64] = {
    let mut masks = [0u64; 64];
    let mut i = 0;
    while i < 64 {
        masks[i] = relevant_mask_bishop(i);
        i += 1;
    }
    masks
};

pub static BISHOP_ATTACKS: [[BitBoard; 2usize.pow((64 - MAGIC_SHIFT) as u32)]; 64] = {
    let mut table = [[BitBoard::EMPTY; 2usize.pow((64 - MAGIC_SHIFT) as u32)]; 64];
    let mut square_idx = 0;
    while square_idx < 64 {
        table[square_idx] = build_bishop_table(square_idx, BISHOP_MAGICS[square_idx]);
        square_idx += 1;
    }
    table
};

/// The edges of the mask are deliberately ignored, since it is
/// the last available square either way (cannot move through)
pub(super) const fn relevant_mask_bishop(square_idx: usize) -> u64 {
    let row = square_idx / 8;
    let col = square_idx % 8;
    let mut mask = 0u64;

    // Up-right
    let mut new_row = row + 1;
    let mut new_col = col + 1;
    while new_row < 7 && new_col < 7 {
        mask |= 1 << (new_row * 8 + new_col);
        new_row += 1;
        new_col += 1;
    }

    // Up-left
    let mut new_row = row + 1;
    let mut new_col = col as i32 - 1;
    while new_row < 7 && new_col > 0 {
        mask |= 1 << (new_row * 8 + new_col as usize);
        new_row += 1;
        new_col -= 1;
    }

    // Down-right
    let mut new_row = row as i32 - 1;
    let mut new_col = col + 1;
    while new_row > 0 && new_col < 7 {
        mask |= 1 << (new_row as usize * 8 + new_col);
        new_row -= 1;
        new_col += 1;
    }

    // Down-left
    let mut new_row = row as i32 - 1;
    let mut new_col = col as i32 - 1;
    while new_row > 0 && new_col > 0 {
        mask |= 1 << (new_row as usize * 8 + new_col as usize);
        new_row -= 1;
        new_col -= 1;
    }

    mask
}

const fn build_bishop_table(
    sq: usize,
    magic: u64,
) -> [BitBoard; 2usize.pow((64 - MAGIC_SHIFT) as u32)] {
    let mask = relevant_mask_bishop(sq);
    let mut table = [BitBoard::EMPTY; 2usize.pow((64 - MAGIC_SHIFT) as u32)];

    let mut subset = mask;
    loop {
        let idx = (subset.wrapping_mul(magic) >> MAGIC_SHIFT) as usize;
        table[idx] = BitBoard::from_u64(slow_bishop_attacks(sq, subset));
        if subset == 0 {
            break;
        }
        subset = (subset - 1) & mask;
    }

    table
}

pub const fn slow_bishop_attacks(square_idx: usize, occ: u64) -> u64 {
    let row = square_idx / 8;
    let col = square_idx % 8;
    let mut attacks = 0u64;

    // Up-right
    let mut new_row = row + 1;
    let mut new_col = col + 1;
    while new_row < 8 && new_col < 8 {
        let bit = 1u64 << (new_row * 8 + new_col);
        attacks |= bit;
        if occ & bit != 0 {
            break;
        }
        new_row += 1;
        new_col += 1;
    }

    // Up-left
    let mut new_row = row + 1;
    let mut new_col = col as i32 - 1;
    while new_row < 8 && new_col >= 0 {
        let bit = 1u64 << (new_row * 8 + new_col as usize);
        attacks |= bit;
        if occ & bit != 0 {
            break;
        }
        new_row += 1;
        new_col -= 1;
    }

    // Down-right
    let mut new_row = row as i32 - 1;
    let mut new_col = col + 1;
    while new_row >= 0 && new_col < 8 {
        let bit = 1u64 << (new_row as usize * 8 + new_col);
        attacks |= bit;
        if occ & bit != 0 {
            break;
        }
        new_row -= 1;
        new_col += 1;
    }

    // Down-left
    let mut new_row = row as i32 - 1;
    let mut new_col = col as i32 - 1;
    while new_row >= 0 && new_col >= 0 {
        let bit = 1u64 << (new_row as usize * 8 + new_col as usize);
        attacks |= bit;
        if occ & bit != 0 {
            break;
        }
        new_row -= 1;
        new_col -= 1;
    }

    attacks
}

#[inline(always)]
pub fn get_attacks_bishop(pos: Square, friendly: BitBoard, enemy: BitBoard) -> BitBoard {
    let sq = pos.idx();
    let occ = (friendly | enemy).to_u64() & BISHOP_MASKS[sq];
    let idx = ((occ.wrapping_mul(BISHOP_MAGICS[sq])) >> MAGIC_SHIFT) as usize;
    BISHOP_ATTACKS[sq][idx]
}

#[inline(always)]
pub fn get_pl_moves_bishop(moves: &mut MoveList, pos: Square, friendly: BitBoard, enemy: BitBoard) {
    let attacks = get_attacks_bishop(pos, friendly, enemy);
    for to in (attacks & enemy).iter() {
        moves.push(Move::new(Capture, pos, to));
    }
    for to in (attacks & !friendly & !enemy).iter() {
        moves.push(Move::new(QuietMove, pos, to));
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::chess::moves::Move;
    use crate::chess::moves::MoveKind::{Capture, QuietMove};
    use std::str::FromStr;

    struct TestCase {
        pos: &'static str,
        friendly: &'static [&'static str],
        enemy: &'static [&'static str],
        expected_moves: Vec<Move>,
    }

    fn run_test(case: TestCase) {
        let pos = Square::from_str(case.pos).unwrap();
        let mut friendly = BitBoard::EMPTY;
        for &sq in case.friendly {
            friendly.set(Square::from_str(sq).unwrap());
        }
        let mut enemy = BitBoard::EMPTY;
        for &sq in case.enemy {
            enemy.set(Square::from_str(sq).unwrap());
        }

        let mut got = MoveList::new();
        get_pl_moves_bishop(&mut got, pos, friendly, enemy);
        let want = case.expected_moves;

        assert_eq!(
            got.len(),
            want.len(),
            "move count mismatch: {got:?} vs {want:?}"
        );
        for m in want {
            assert!(got.contains(&m), "missing move {m:?} in {got:?}");
        }
    }

    // Test bishop in middle of board
    #[test]
    fn test_middle() {
        let orig_square_str = "e5";
        let orig_square = Square::from_str(orig_square_str).unwrap();
        run_test(TestCase {
            pos: orig_square_str,
            friendly: &[],
            enemy: &[],
            expected_moves: vec![
                Move::new(QuietMove, orig_square, Square::from_str("d4").unwrap()),
                Move::new(QuietMove, orig_square, Square::from_str("c3").unwrap()),
                Move::new(QuietMove, orig_square, Square::from_str("b2").unwrap()),
                Move::new(QuietMove, orig_square, Square::from_str("a1").unwrap()),
                Move::new(QuietMove, orig_square, Square::from_str("f6").unwrap()),
                Move::new(QuietMove, orig_square, Square::from_str("g7").unwrap()),
                Move::new(QuietMove, orig_square, Square::from_str("h8").unwrap()),
                Move::new(QuietMove, orig_square, Square::from_str("d6").unwrap()),
                Move::new(QuietMove, orig_square, Square::from_str("c7").unwrap()),
                Move::new(QuietMove, orig_square, Square::from_str("b8").unwrap()),
                Move::new(QuietMove, orig_square, Square::from_str("f4").unwrap()),
                Move::new(QuietMove, orig_square, Square::from_str("g3").unwrap()),
                Move::new(QuietMove, orig_square, Square::from_str("h2").unwrap()),
            ],
        })
    }

    // Bishop a1 with friendly blocked b2 (no legal moves)
    #[test]
    fn test_a1_blocked_friendly() {
        run_test(TestCase {
            pos: "a1",
            friendly: &["b2"],
            enemy: &[],
            expected_moves: vec![],
        })
    }

    // Bishop a1 with enemy blocked b2 (b2 only legal move)
    #[test]
    fn test_a1_blocked_enemy() {
        run_test(TestCase {
            pos: "a1",
            friendly: &[],
            enemy: &["b2"],
            expected_moves: vec![Move::new(
                Capture,
                Square::from_str("a1").unwrap(),
                Square::from_str("b2").unwrap(),
            )],
        })
    }
}
